// The external automation surface moved verbatim out of main.js (M11): the window.hallowmere
// read/act API and the two document.modelContext tools registered on top of it. Its key set,
// tool names and both inputSchemas are frozen (PLAN.md constraint 10) and pinned by
// tests/automation-surface.test.mjs, which now drives this function instead of slicing source.
//
// window and document became the injected windowTarget/documentTarget so the test can record
// what is assigned and registered; that is the only change to the three statements below,
// besides the two ctx renames. The AbortController and its 'pagehide' abort stay inside the
// registerTool branch, so the surface keeps registering pagehide #2 -- after session-lifecycle's
// pagehide #1 and page-activity's pair, before the world preview's dispose.
//
// Free identifiers: npcDialogue/questSummary (./campaign.js), hasLineOfSight (./combat.js),
// MAPS (./regions.js) and T (three, only T.Vector3, so the core build) stay plain imports.
// AbortController, Promise, Object, Error, Number, Math and console are globals.
//
// ctx renames for names that were bare module-scope bindings in main.js: ctx.awaken (M7's
// createGameAudio) and ctx.perform (x2, main.js's own perform, assigned onto ctx in the
// wiring block). Everything else was already spelled ctx.* in main.js.
import * as T from './vendor/three.core.js';
import {npcDialogue,questSummary} from './campaign.js';
import {hasLineOfSight} from './combat.js';
import {MAPS} from './regions.js';
export function installAutomationSurface(ctx,{windowTarget=window,documentTarget=document}={}){
 // Assistive tools call the same movement, conversations, and combat paths as the visible controls.
 windowTarget.hallowmere={getState:()=>({...ctx.state,cooldowns:{...ctx.state.cooldowns},ready:ctx.ready,paused:ctx.paused,backgrounded:ctx.backgrounded,mode:ctx.sessionMode,simulationPaused:!ctx.network?.connected||ctx.sessionMode==='single-player'&&(ctx.paused||ctx.backgrounded||!!ctx.rosterPicker?.open),multiplayer:{connected:ctx.sessionMode==='multiplayer'&&!!ctx.network?.connected,worldId:ctx.network?.worldId,players:ctx.lastSnapshot?.players||[],votes:ctx.lastSnapshot?.votes||[]},modal:ctx.modalKind,interior:ctx.player?ctx.environment.currentBuilding(ctx.player.position)?.id??null:null,buildings:ctx.environment?.buildings.map(b=>({id:b.id,name:b.name,chapel:b.chapel,locked:!b.doorCollider.disabled,inside:b.inside,door:{...b.door},entry:{...b.entry},exit:{...b.exit}})),dialogue:ctx.modalKind==='npc'?npcDialogue(ctx.state,ctx.currentNpc):null,objective:questSummary(ctx.state),mapId:ctx.renderedMap,bounds:ctx.worldBounds(),interactions:ctx.regionInteractions(),hazards:ctx.lastSnapshot?.hazards||[],audio:ctx.audio.getState(),targeting:{hoveredEnemy:ctx.mouseAction?.kind==='enemy'?ctx.mouseAction.target.id:null,lockedEnemy:ctx.lockedEnemy?.id??null,highlightedEnemy:ctx.mouseTargeting?.selected?.id??null},player:ctx.player?{x:ctx.player.position.x,z:ctx.player.position.z,moving:!!ctx.moveTarget,attacking:ctx.attackHeld}:null,...ctx.life?.getState(),enemies:ctx.enemies.filter(e=>!e.dead).map(e=>({id:e.id,type:e.type,zone:e.zone,hp:e.hp,x:e.model.position.x,z:e.model.position.z,phase:e.phase,lineOfSight:hasLineOfSight(ctx.player.position,e.model.position,ctx.environment.obstacles)})),drawCalls:ctx.renderer?.info.render.calls}),showControls:()=>ctx.showModal('help'),pause:()=>ctx.showModal('pause'),resume:ctx.closeModal};
 const modelContext=documentTarget.modelContext;
 if(modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.warn('Game tool registration unavailable',error));}catch(error){console.warn('Game tool registration unavailable',error);}};register({name:'get_vigil_state',title:'Read the vigil',description:'Read health, position, objectives, nearby villagers and dialogue choices, ground loot, available forage plants, the food pouch, active essence regeneration, owned equipment, enemies, and cooldowns.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('No input fields are accepted.');return windowTarget.hallowmere.getState();}});register({name:'control_warden',title:'Control the Warden',description:'Use normal game controls. Move to x,z; attack with optional hold (mouse hold), interact with a villager, loot, plant, or building id (walks closer or enters through its door), choose a displayed NPC service, open inventory, consume pouch food by id while Inventory is open, equip an owned item, use a spell, pause or resume. Costs, distance, collisions, cooldowns, and health apply.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['move','attack','bolt','dodge','nova','heal','pause','resume','interact','service','inventory','equip','consume']},x:{type:'number',minimum:Math.min(...Object.values(MAPS).map(m=>m.bounds.minX)),maximum:Math.max(...Object.values(MAPS).map(m=>m.bounds.maxX))},z:{type:'number',minimum:Math.min(...Object.values(MAPS).map(m=>m.bounds.minZ)),maximum:Math.max(...Object.values(MAPS).map(m=>m.bounds.maxZ))},id:{type:'string'},choice:{type:'string'},hold:{type:'boolean'}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const valid=['move','attack','bolt','dodge','nova','heal','pause','resume','interact','service','inventory','equip','consume'];if(!input||!valid.includes(input.action)||Object.keys(input).some(k=>!['action','x','z','id','choice','hold'].includes(k)))throw Error('Invalid Warden action.');if(!ctx.ready)throw Error('The game is still loading.');if(input.x!==undefined&&(!Number.isFinite(input.x)||input.x<ctx.worldBounds().minX||input.x>ctx.worldBounds().maxX))throw Error('x is outside the world.');if(input.z!==undefined&&(!Number.isFinite(input.z)||input.z<ctx.worldBounds().minZ||input.z>ctx.worldBounds().maxZ))throw Error('z is outside the world.');if((input.x===undefined)!==(input.z===undefined))throw Error('Supply both x and z.');if(input.action==='move'&&input.x===undefined)throw Error('Movement requires x and z.');if(input.hold!==undefined&&typeof input.hold!=='boolean')throw Error('hold must be a boolean.');if(input.action==='pause'){ctx.showModal('pause');return{paused:ctx.paused};}if(input.action==='resume'){ctx.closeModal();return{paused:ctx.paused};}if(input.action==='service')return ctx.serviceNpc(input.choice);if(input.action==='equip')return ctx.equipOwnedItem(input.id);if(input.action==='consume')return ctx.consumePouchItem(input.id);if(ctx.paused||ctx.backgrounded||ctx.state.ended)throw Error('The vigil is paused, in the background, or ended.');ctx.awaken();if(input.action==='inventory'){ctx.showModal('inventory');return{opened:true};}if(input.action==='interact')return ctx.interact(input.id);if(input.x!==undefined){ctx.targetWorld.set(input.x,0,input.z);ctx.angle=Math.atan2(input.x-ctx.player.position.x,input.z-ctx.player.position.z);ctx.aimActive=true;}else ctx.aimActive=false;let performed;if(input.action==='move')performed=ctx.setDestination(new T.Vector3(input.x,0,input.z));else if(input.action==='attack'&&input.hold!==undefined){ctx.attackHeld=input.hold;ctx.lockedEnemy=ctx.attackHeld?(input.id?ctx.enemies.find(e=>e.id===input.id&&!e.dead):input.x!==undefined?ctx.enemyAtPoint(ctx.targetWorld):ctx.nearestEnemy(12)):null;ctx.moveTarget=null;ctx.movePath=[];if(ctx.lockedEnemy){ctx.aimActive=false;ctx.angle=Math.atan2(ctx.lockedEnemy.model.position.x-ctx.player.position.x,ctx.lockedEnemy.model.position.z-ctx.player.position.z);}performed=ctx.attackHeld?ctx.perform('attack'):true;}else performed=ctx.perform(input.action);ctx.updateUI();return{performed,health:ctx.state.hp,essence:Math.floor(ctx.state.mana),cooldown:ctx.state.cooldowns[input.action]??0};}});windowTarget.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
}
